      "path": "src/relay.ts",
      "content": "/**\n * LAN relay: re-exposes the pool's loopback OpenAI shim on a LAN address, so a\n * second machine, a phone, or another editor can talk to the pool with a plain\n * OpenAI client.\n *\n * WHY A SEPARATE LISTENER INSTEAD OF BINDING THE SHIM TO 0.0.0.0\n *\n * The shim's own secret is minted per process and re-generated on every start.\n * Binding the shim directly would mean handing that secret to every device on\n * the network: one DSH restart later every client that saved it is broken, and\n * in the meantime it has been written into whatever config file each client\n * keeps its API key in.\n *\n * So the relay owns a key of its own, rotatable from the card, and holds the\n * shim secret inside the process. A client that has the relay key can reach the\n * pool through the relay. The shim secret is never written to a response and\n * never leaves this process — that separation is the whole security model, not\n * a detail.\n *\n * The relay translates nothing. It forwards a small whitelisted set of paths\n * verbatim and copies the upstream status, headers, and body back, so a remote\n * caller sees exactly the shape the shim produces — the shape the tests pin.\n * Translating here would put a second, drifting copy of the wire format between\n * the client and the code that is actually verified.\n *\n * @module dsh-xdpool/relay\n */\nimport { randomBytes, timingSafeEqual } from 'node:crypto'\nimport { createServer, request as httpRequest } from 'node:http'\nimport { request as httpsRequest } from 'node:https'\nimport type { IncomingHttpHeaders, IncomingMessage, Server, ServerResponse } from 'node:http'\nimport type { WorkBuddyShim } from './shim.ts'\nimport { RELAY_HOP_HEADER } from './shim.ts'\nimport type { GatewayModelEntry } from './shim.ts'\nimport type { PoolWebRelayStatus } from './status-paths.ts'\n/**\n * Marked on every forwarded request so a relay pointed at its own address\n * refuses instead of looping, and so the shim can tell a LAN client from the\n * host's own adapter. Re-exported for callers that read the relay's contract\n * rather than the shim's.\n */\nexport { RELAY_HOP_HEADER }\n/**\n * The only paths this relay forwards.\n *\n * Deliberately exactly the routes the shim serves. Anything else is refused\n * with 404 *before* a byte of the body is read or forwarded, so the relay can\n * never become a general-purpose proxy for whatever else might answer on the\n * shim's port.\n */\nexport const RELAY_FORWARDED_PATHS: ReadonlySet<string> = new Set([\n  '/v1/models',\n  '/v1/chat/completions',\n])\n/** Default LAN port. Loopback by default; see {@link RELAY_HOSTS}. */\nexport const RELAY_DEFAULT_PORT = 8326\n/**\n * Bind addresses the user may choose.\n *\n * `127.0.0.1` means \"no off-box client can reach this at all\", and it is the\n * default: listening on every interface is a decision to make on purpose, not a\n * side effect of a feature existing.\n */\nexport const RELAY_HOSTS: readonly string[] = ['127.0.0.1', '0.0.0.0']\nexport interface RelayLogger {\n  info?(...args: unknown[]): void\n  warn(...args: unknown[]): void\n  error?(...args: unknown[]): void\n}\nexport interface RelaySettings {\n  enabled: boolean\n  host: string\n  port: number\n  key: string\n}\nexport interface PoolRelayStatus {\n  enabled: boolean\n  /** Whether a listener is actually bound right now. */\n  listening: boolean\n  host: string\n  port: number\n  /** Where a client should point; '' until something is listening. */\n  endpoint: string\n  /**\n   * The relay key in full.\n   *\n   * Returned on purpose: the card has to show it once so the user can copy it\n   * into the other device. This is the key WE minted for LAN clients, not the\n   * shim secret, and it grants nothing beyond reaching the pool.\n   */\n  key: string\n  /** Why nothing is bound; '' when there is nothing to explain. */\n  error: string\n}\nexport interface PoolRelay {\n  /** Settles after the first bind attempt; never rejects. */\n  ready: Promise<void>\n  status(): Promise<PoolRelayStatus>\n  /**\n   * Re-read the settings and re-evaluate the listener.\n   *\n   * Called after every settings write. Key and switch changes take effect on the\n   * next request because the settings are read per request; only a change of\n   * address or port needs the listener rebuilt, which is why this exists instead\n   * of making the caller tear the relay down and build it again.\n   */\n  sync(): Promise<PoolRelayStatus>\n  close(): Promise<void>\n}\nexport interface PoolRelayOptions {\n  /** The loopback shim to forward to. */\n  shim: WorkBuddyShim\n  /** Current settings, re-read on every request and every status call. */\n  read: () => RelaySettings\n  logger?: RelayLogger\n}\n/**\n * Bind address and port, or undefined when the settings cannot describe one.\n *\n * An out-of-range port is treated as \"not configured\" rather than clamped:\n * silently listening somewhere other than where the user asked is worse than\n * declining to start and saying so.\n */\nfunction bindTarget(settings: RelaySettings): { host: string; port: number } | undefined {\n  const host = RELAY_HOSTS.includes(settings.host) ? settings.host : RELAY_HOSTS[0]\n  if (host === undefined) return undefined\n  const port = settings.port\n  // 0 is honoured as \"let the OS pick\", which is what a caller wants when it\n  // only needs a port to test against. It can never come from the stored\n  // settings: the store clears a 0 rather than writing it.\n  if (!Number.isInteger(port) || port < 0 || port > 65_535) return undefined\n  return { host, port }\n}\n/** Constant-time key comparison that tolerates a missing or wrong-length key. */\nfunction keyMatches(presented: string, expected: string): boolean {\n  if (expected === '') return false\n  const a = Buffer.from(presented, 'utf8')\n  const b = Buffer.from(expected, 'utf8')\n  if (a.length !== b.length) return false\n  return timingSafeEqual(a, b)\n}\n/**\n * The caller's token, falling back to `x-api-key`.\n *\n * Both spellings are read because Anthropic-compatible clients send the latter,\n * and a relay that only understood one of them would look like a dead network\n * to half the clients it exists for.\n */\nfunction bearerOf(req: IncomingMessage): string {\n  const header = req.headers.authorization\n  if (typeof header === 'string') {\n    const match = /^Bearer\\s+(.+)$/iu.exec(header.trim())\n    if (match?.[1] !== undefined) return match[1].trim()\n  }\n  const alt = req.headers['x-api-key']\n  if (typeof alt === 'string') return alt.trim()\n  return ''\n}\n/** Connection-scoped headers, which must not be copied onto the next hop. */\nconst HOP_BY_HOP: ReadonlySet<string> = new Set([\n  'connection',\n  'keep-alive',\n  'proxy-authenticate',\n  'proxy-authorization',\n  'te',\n  'trailer',\n  'transfer-encoding',\n  'upgrade',\n])\n/**\n * Headers for the upstream hop: the caller's, minus the hop-by-hop set and the\n * ones that must not travel onward, plus our own hop marker.\n *\n * `x-api-key` is dropped as well as `authorization`: a client using the\n * Anthropic spelling would otherwise have its relay key forwarded verbatim to\n * the shim, where it does nothing and is a leaked secret sitting in a log.\n */\nfunction upstreamHeaders(req: IncomingMessage, shimToken: string): IncomingHttpHeaders {\n  const headers: IncomingHttpHeaders = {}\n  for (const [name, value] of Object.entries(req.headers)) {\n    const lower = name.toLowerCase()\n    if (HOP_BY_HOP.has(lower)) continue\n    if (lower === 'host' || lower === 'authorization' || lower === 'x-api-key') continue\n    if (lower === RELAY_HOP_HEADER) continue\n    if (value !== undefined) headers[lower] = value\n  }\n  headers.authorization = `Bearer ${shimToken}`\n  headers[RELAY_HOP_HEADER] = '1'\n  return headers\n}\nfunction writeJson(res: ServerResponse, status: number, code: string, message: string): void {\n  const body = `${JSON.stringify({ error: { message, type: code, code } })}\\n`\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': Buffer.byteLength(body),\n  })\n  res.end(body)\n}\n/**\n * Build the relay.\n *\n * Nothing binds until {@link PoolRelay.ready} settles, so a port clash becomes a\n * status the card can display instead of an exception that takes plugin startup\n * down with it.\n */\nexport function createPoolRelay(options: PoolRelayOptions): PoolRelay {\n  const { shim, logger } = options\n  let server: Server | undefined\n  let listening = false\n  let boundHost = ''\n  let boundPort = 0\n  let bindError = ''\n  /** Re-read per request; a throwing reader must not take the relay down. */\n  const settingsOf = (): RelaySettings => {\n    try {\n      return options.read()\n    } catch (error) {\n      logger?.warn(`xdpool relay: settings unreadable, treating the relay as off: ${String(error)}`)\n      return { enabled: false, host: RELAY_HOSTS[0] ?? '127.0.0.1', port: RELAY_DEFAULT_PORT, key: '' }\n    }\n  }\n  const stop = (): Promise<void> =>\n    new Promise<void>(resolve => {\n      const current = server\n      server = undefined\n      listening = false\n      boundHost = ''\n      boundPort = 0\n      if (current === undefined) {\n        resolve()\n        return\n      }\n      // Idle keep-alive sockets hold the port open past `close`, so they are\n      // dropped outright. A client mid-request goes with them: the relay is\n      // going away and there is nowhere left to finish the response.\n      current.closeAllConnections?.()\n      current.close(() => resolve())\n    })\n  const start = (host: string, port: number): Promise<void> =>\n    new Promise<void>(resolve => {\n      const next = createServer(handle)\n      const fail = (error: unknown): void => {\n        bindError = error instanceof Error ? error.message : String(error)\n        logger?.warn(`xdpool relay: cannot bind ${host}:${port} — ${bindError}`)\n        next.close(() => resolve())\n      }\n      next.once('error', fail)\n      next.listen(port, host, () => {\n        next.removeListener('error', fail)\n        const address = next.address()\n        if (address === null || typeof address === 'string') {\n          bindError = 'the listener bound an address the relay cannot advertise'\n          next.close(() => resolve())\n          return\n        }\n        server = next\n        listening = true\n        boundHost = host\n        boundPort = address.port\n        bindError = ''\n        // The port actually bound is reported, not the requested one: port 0\n        // asks the OS for a free port and the caller has to be told which.\n        logger?.info?.(`xdpool relay: listening on http://${host}:${address.port}/v1`)\n        resolve()\n      })\n    })\n  function handle(req: IncomingMessage, res: ServerResponse): void {\n    const settings = settingsOf()\n    // The loop marker is refused before the switch is even consulted. A relay\n    // that has been pointed at its own address would otherwise answer its own\n    // \"you are switched off\" 503 in a loop; refusing the hop unconditionally is\n    // what makes a misconfiguration diagnosable instead of a request storm.\n    if (req.headers[RELAY_HOP_HEADER] !== undefined) {\n      writeJson(res, 508, 'relay_loop', 'this request already came through the relay')\n      return\n    }\n    // Switch before key: a disabled relay holds no listener, so this only fires\n    // for a request already in flight when the user turned it off — and there,\n    // 503 says \"off\" where a 401 would tell the client its key is stale and\n    // prompt for one that would not help.\n    if (!settings.enabled) {\n      writeJson(res, 503, 'relay_disabled', 'the XD Pool LAN relay is switched off')\n      return\n    }\n    if (!keyMatches(bearerOf(req), settings.key)) {\n      writeJson(res, 401, 'relay_unauthorized', 'a valid XD Pool relay key is required')\n      return\n    }\n    const path = (req.url ?? '').split('?')[0] ?? ''\n    if (!RELAY_FORWARDED_PATHS.has(path)) {\n      writeJson(res, 404, 'relay_no_route', `${path} is not a path this relay forwards`)\n      return\n    }\n    const target = new URL(`${shim.baseUrl()}${path}`)\n    const send = target.protocol === 'https:' ? httpsRequest : httpRequest\n    const upstream = send(\n      {\n        protocol: target.protocol,\n        hostname: target.hostname,\n        port: target.port === '' ? 80 : Number(target.port),\n        method: req.method,\n        path: `${target.pathname}${target.search}`,\n        headers: upstreamHeaders(req, shim.token()),\n      },\n      answer => {\n        res.writeHead(answer.statusCode ?? 502, answer.headers)\n        answer.pipe(res)\n      },\n    )\n    // A caller that walks away mid-request must not leave the pool burning an\n    // account's quota on a reply nobody will read.\n    res.once('close', () => {\n      if (!res.writableEnded) upstream.destroy()\n    })\n    upstream.on('error', error => {\n      if (res.headersSent) {\n        res.end()\n        return\n      }\n      writeJson(res, 502, 'relay_unreachable', `the pool shim did not answer: ${String(error)}`)\n    })\n    // Streamed, not buffered: a 64 MB body must not be held in memory here, and\n    // streaming keeps time-to-first-token on the LAN as short as on loopback.\n    req.pipe(upstream)\n  }\n  const sync = async (): Promise<void> => {\n    const settings = settingsOf()\n    const target = bindTarget(settings)\n    if (!settings.enabled || target === undefined) {\n      await stop()\n      bindError =\n        settings.enabled && target === undefined\n          ? `port ${settings.port} is not a port this relay can bind`\n          : ''\n      return\n    }\n    if (satisfied(target.host, target.port)) return\n    await stop()\n    await start(target.host, target.port)\n  }\n  /**\n   * Whether the current listener already satisfies what the settings ask for.\n   *\n   * Compared against the REQUESTED port, not the bound one: binding port 0\n   * resolves to some port the OS chose, so comparing the resolved value against\n   * the request of 0 would never match and every sync would rebind — handing the\n   * user a different port each time they saved anything.\n   */\n  const satisfied = (host: string, requestedPort: number): boolean =>\n    server !== undefined && host === boundHost && (requestedPort === 0 || requestedPort === boundPort)\n  const status = async (): Promise<PoolRelayStatus> => {\n    const settings = settingsOf()\n    return {\n      enabled: settings.enabled,\n      listening,\n      host: boundHost === '' ? settings.host : boundHost,\n      port: boundPort === 0 ? settings.port : boundPort,\n      endpoint: listening ? `http://${boundHost}:${boundPort}/v1` : '',\n      key: settings.key,\n      error: bindError,\n    }\n  }\n  const ready = sync().then(() => undefined)\n  return {\n    ready,\n    status,\n    sync: async (): Promise<PoolRelayStatus> => {\n      await sync()\n      return status()\n    },\n    close: stop,\n  }\n}\n/** A fresh relay key: 32 random bytes, URL-safe so it survives a copy-paste. */\nexport function newRelayKey(): string {\n  return randomBytes(32).toString('base64url')\n}\n/**\n * Compose the relay document the Gateway card renders.\n *\n * Extracted, and awaited HERE, because the bug this shape exists to prevent is\n * invisible at the call site: `status()` is async, and\n * `{ ...relay.status(), candidates }` spreads a PENDING PROMISE, which yields no\n * own properties at all. The document then carries the new fields and silently\n * drops `enabled`, `listening`, `host`, `port`, `key` and `error` — a card with no\n * switch, no key and no endpoint, served over HTTP 200 with nothing to indicate it\n * broke. This happened when the picker was added; the assertions below are the\n * reason it cannot happen quietly again.\n *\n * Every input is a function so a test can hand it a rejecting roster and still\n * require the rest of the document to arrive.\n */\nexport async function relayDocumentOf(input: {\n  status: () => Promise<PoolRelayStatus>\n  shared: () => readonly string[] | undefined\n  roster: () => Promise<readonly GatewayModelEntry[]>\n  warn?: (error: unknown) => void\n}): Promise<PoolWebRelayStatus> {\n  const status = await input.status()\n  let candidates: readonly GatewayModelEntry[]\n  try {\n    candidates = await input.roster()\n  } catch (error: unknown) {\n    // A roster that cannot be read must not take the panel down with it: the\n    // switch, the key and the address are all still usable, and the picker is the\n    // one part that can honestly say \"nothing to show right now\".\n    input.warn?.(error)\n    candidates = []\n  }\n  const shared = input.shared()\n  return {\n    ...status,\n    candidates,\n    ...(shared === undefined ? {} : { shared }),\n  }\n}"
    },
    {
      "path": "src/scheduler.ts",
      "content": "/**\n * Points automation: the daily pass that keeps every account earning.\n *\n * Three independent jobs run on their own hour lists:\n *\n * - `report` (default 10:00) sends one chat-activity event per account per day.\n *   This is what lights the growth streak and unlocks the `first_buddy` family,\n *   so it must run BEFORE the task-centre pass — otherwise the task list is\n *   read before its counters can have moved.\n * - `tasks`  (default 11:00) enrols every open task and claims every reward the\n *   account has already earned.\n * - `checkin` (default 09:00) is the plain daily check-in.\n *\n * Scheduling follows the reference panel's model rather than a cron: the loop\n * wakes once a minute, and a job fires when the local hour matches one of its\n * configured hours and it has not yet run today. \"Run today\" is tracked per job\n * as a `YYYY-MM-DD` string, which self-resets at midnight.\n *\n * Everything is serial and failure-isolated: one account throwing skips that\n * account and continues with the next, and one job throwing never stops the\n * loop. `global`-region accounts are skipped entirely — the international\n * gateway has no growth/task system, so calling it would only produce noise.\n */\n\nimport type { WorkBuddyAccount, WorkBuddyAccountPool, WorkBuddyCredential } from './accounts'\nimport { randomUUID } from 'node:crypto'\nimport { isAlreadyCheckin, isNoCompensation, regionOf } from './upstream'\nimport type { WorkBuddyTask, WorkBuddyUpstreamClient } from './upstream'\nimport {\n  APPEARANCE_THEME_KEY, LIGHTHOUSE_EXPERT_ID, automationChain, appearanceChain, buddyAppChain,\n  canvasChain, chatChain, expertActualUseEvent, expertChatEvents, expertSummonEvents,\n  libraryReadChain, playbookChain, skillChain, templateChains,\n} from './task-events.ts'\nimport type { MarketExpert, TaskEventChain } from './task-events.ts'\nimport { DEFAULT_AUTOMATION_HOURS } from './status-paths.ts'\n\n/** Per-account gap between upstream calls, so a pool of accounts is not a burst. */\nexport const AUTOMATION_ACCOUNT_DELAY_MS = 800\n/**\n * Gap between two expert summon chains.\n *\n * The scorer does not count two expert uses that land back to back — it reads\n * them as one session — so a pass that fires five chains in a row lights up\n * fewer than five. The reference panel settled on several seconds of real\n * usage rhythm; measured here: a 300ms gap scored 1 of 2 chains, while this\n * gap scores every one.\n */\nexport const EXPERT_SUMMON_GAP_MS = 6_000\n\n/** How often the loop wakes to look for a due job. */\n\n/**\n * How long to wait for event scoring to land before re-reading the task list.\n *\n * Scoring is asynchronous on the upstream side, so an immediate re-read still\n * shows the old progress and the claim pass would skip a task that is in fact\n * now claimable. Measured: the chain is reflected by about eight seconds.\n */\nexport const EVENT_SCORE_WAIT_MS = 9_000\n\n/** The app the buddy chain enters, satisfying both buddy tasks. */\nconst BUDDY_APP_ID = 'cb_y5Dy46tPQGGWtueMxXbe'\nconst BUDDY_APP_NAME = '企鹅教师助手'\n\n/**\n * The fallback record for the 腾讯轻量云 expert, used when the marketplace\n * listing cannot be read. The id is the one the task is scored against.\n */\nconst LIGHTHOUSE_EXPERT: MarketExpert = {\n  expertId: LIGHTHOUSE_EXPERT_ID,\n  expertType: 'agent',\n  displayName: '腾讯轻量云专家',\n  profession: '腾讯轻量云专家',\n  version: '1.0.2',\n  categories: [],\n}\n\n/**\n * Tasks with a chain in this module.\n *\n * Membership is the filter the pass uses before it tries to build one, so a\n * task with no chain costs no upstream call. It has to be kept in step with\n * `chainsFor`'s switch: a code listed here with no case would be read and then\n * silently skipped.\n */\nconst EVENT_CHAIN_BUILDERS: Readonly<Record<string, true>> = {\n  Buddy_App: true,\n  Buddy_App_QQ: true,\n  create_canvas: true,\n  automation_1: true,\n  RichMeow_Chat: true,\n  playbook_prompt: true,\n  template_5: true,\n  Hp_Appearance: true,\n  Library_read: true,\n  skill_1: true,\n  expert_5: true,\n  Expert_team_use_3: true,\n  Expert_lighthouse: true,\n}\n\nexport const AUTOMATION_TICK_MS = 60_000\n\n/** Which jobs the automation runs, and when. */\n/**\n * The persisted daily earnings ledger.\n *\n * `date` is the local day the counters belong to: a ledger from a previous day\n * is discarded on load rather than carried forward as \"today\".\n */\nexport interface AutomationLedger {\n  date: string\n  accounts: Record<string, AutomationAccountEarnings>\n}\n\nexport interface AutomationOptions {\n  /** Master switch; false stops every job. */\n  enabled?: boolean\n  /** Hour list for the daily check-in job. */\n  checkinHours?: readonly number[]\n  /** Hour list for the task-centre job (accept + claim). */\n  taskHours?: readonly number[]\n  /** Hour list for the activity-report job. */\n  reportHours?: readonly number[]\n  /** Hour list for the streak-redemption job. */\n  streakHours?: readonly number[]\n  /** Hour list for the buddy travel job. */\n  travelHours?: readonly number[]\n  /** Hour list for the outage-compensation claim. */\n  compensationHours?: readonly number[]\n  /** Per-account serial delay, in milliseconds. */\n  accountDelayMs?: number\n  /** Override the gap between expert chains, in milliseconds (tests use 0). */\n  expertGapMs?: number\n  /** Override the event-scoring wait, in milliseconds (tests use 0). */\n  eventScoreWaitMs?: number\n  /** Override the clock, for tests. */\n  now?: () => Date\n  /** Logger; defaults to a no-op so tests stay quiet. */\n  logger?: SchedulerLogger\n  /**\n   * Persist the daily earnings ledger, and restore it on construction.\n   *\n   * The ledger cannot live only in memory: a host restart mid-day would wipe\n   * what the automation already earned, and the card would show nothing for\n   * rewards that really were collected.\n   */\n  loadEarnings?: () => AutomationLedger | undefined\n  saveEarnings?: (ledger: AutomationLedger) => void\n}\n\n/** Logger surface, kept structural so any host logger fits. */\nexport interface SchedulerLogger {\n  info?(...args: unknown[]): void\n  warn?(...args: unknown[]): void\n}\n\n/** One job's last-run record, surfaced on the status document. */\nexport interface AutomationJobState {\n  /** `YYYY-MM-DD` of the last completed run, or undefined if it never ran. */\n  lastRunDate?: string\n  /**\n   * The scheduled SLOT of the last run, as `YYYY-MM-DDTHH`.\n   *\n   * The tick de-duplicates on this rather than on the date: keying on the date\n   * alone caps every job at one run a day, which is wrong for a job with two\n   * time points — blocking the cat loop's second pass would leave the cat out\n   * until tomorrow. Per slot a job runs once in each configured hour, while a\n   * repeat tick inside the same hour is still refused.\n   */\n  lastRunSlot?: string\n  /**\n   * Every configured slot consumed TODAY, as `YYYY-MM-DDTHH`.\n   *\n   * This is what actually gates a re-run, and it is a SET rather than a single\n   * slot because one field could not express the contract: a job configured for\n   * `[9, 21]` runs twice, and a single \"last slot\" value can only remember one\n   * of them — the second run erased the first, so the 9 o'clock candidate looked\n   * unconsumed again and the job re-fired every hour after 21:00.\n   *\n   * The values are the CONFIGURED hours that were spent, never the clock time\n   * the run happened to finish at. Storing the finish time was the original\n   * defect: the reader compared it against a configured candidate, so the two\n   * almost never matched and the gate stayed open all day.\n   *\n   * In-memory like the rest of `states`: this is a per-process record, and the\n   * catch-up design deliberately re-runs an hour that passed while DSH was\n   * closed. See `automationEarnings` for the ledger that DOES persist.\n   */\n  firedSlots?: readonly string[]\n  /**\n   * The clock slot the last run STARTED in (`YYYY-MM-DDTHH`).\n   *\n   * Separate from {@link firedSlots} on purpose: this is a throttle (\"do not\n   * start twice inside the same hour\"), while `firedSlots` is the schedule\n   * ledger. Conflating the two is what let a catch-up run at 13:00 erase the\n   * record of the 9 o'clock slot.\n   */\n  lastFiredHour?: string\n  /** Epoch ms of the last completed run. */\n  lastRunAtMs?: number\n  /** Accounts that completed without throwing. */\n  ok: number\n  /** Accounts that threw (each one skipped, the run continued). */\n  failed: number\n  /** Credits claimed by the task job on the last run. */\n  credit: number\n  /** Energy claimed by the task job on the last run. */\n  energy: number\n  /** Tasks claimed by the task job on the last run. */\n  claimed: number\n  /** Human-readable summary of the last run. */\n  /**\n   * What this run actually did, in the words of the task board.\n   *\n   * `message` is a count (\"3 accounts, 5 tasks claimed\"); this is the list a\n   * person can check off — the reward titles the pass collected. A row showing\n   * only a bare number cannot answer \"did it do the thing I care about\", which\n   * is the question the panel exists to answer.\n   */\n  detail?: readonly string[]\n  /**\n   * A pending milestone worth naming, when there is one.\n   *\n   * Streak tiers are why this exists: every tier reads `locked` until enough\n   * consecutive days accumulate, and \"locked\" on its own reads as \"broken\"\n   * rather than \"come back in four days\".\n   */\n  progress?: string\n  message?: string\n}\n\n\n/**\n * What the automation earned for ONE account today.\n *\n * Reset at the local day boundary alongside the per-job \"already ran today\"\n * guard, so the card shows today rather than a running total that never\n * answers \"did it do anything for this account recently\".\n */\nexport interface AutomationAccountEarnings {\n  /** Credits the automation claimed from the task centre today. */\n  credit: number\n  /** Energy claimed from the task centre today. */\n  energy: number\n  /** Tasks claimed today. */\n  claimed: number\n  /**\n   * Credits the automation collected from check-in today.\n   *\n   * Kept separate from `credit` because they are different achievements and the\n   * card shows them on their own lines: \"the automation claimed 3 tasks\" and\n   * \"the automation checked in\" are not the same claim to the user.\n   */\n  checkinCredit: number\n  /** Credits from streak redemption + lottery today. */\n  bonusCredit: number\n  /** Credits from the buddy adoption / travel loop today. */\n  travelCredit: number\n  /**\n   * Credits collected from the outage-compensation offer today.\n   *\n   * Its own column for the same reason as `checkinCredit`: a 500-credit\n   * outage refund is a different thing from a 100-credit daily check-in, and\n   * the card lists what earned what.\n   */\n  compensationCredit: number\n  /** Local date the counters belong to. */\n  date: string\n}\n/** What ONE account gained during a single run. */\nexport interface AutomationAccountGain {\n  credit: number\n  energy: number\n  claimed: number\n  checkinCredit: number\n  bonusCredit: number\n  travelCredit: number\n  compensationCredit: number\n}\n\n/** Totals from running the whole ordered pass at once. */\nexport interface AutomationRunSummary {\n  /** How many jobs actually ran (a job with no hour is skipped). */\n  jobsRun: number\n  /** Accounts that finished without error, summed across jobs. */\n  okCount: number\n  /** Accounts that failed, summed across jobs. */\n  failed: number\n  credit: number\n  energy: number\n  claimed: number\n  /**\n   * What each account gained during THIS run, keyed by account id. Only\n   * accounts that gained something appear.\n   */\n  accounts: Readonly<Record<string, AutomationAccountGain>>\n}\n\n/** Automation snapshot for the status document and the card. */\nexport interface AutomationStatus {\n  enabled: boolean\n  /** Whether the loop is running. */\n  running: boolean\n  checkinHours: readonly number[]\n  taskHours: readonly number[]\n  reportHours: readonly number[]\n  streakHours: readonly number[]\n  travelHours: readonly number[]\n  compensationHours: readonly number[]\n  jobs: {\n    checkin: AutomationJobState\n    report: AutomationJobState\n    tasks: AutomationJobState\n    streak: AutomationJobState\n    travel: AutomationJobState\n    compensation: AutomationJobState\n  }\n  /** Claimable tasks seen on the most recent task pass, across accounts. */\n  claimableSeen: number\n  /**\n   * Per-account totals for today, keyed by account id. Only accounts that\n   * actually earned something appear, so the card can render \"no earnings\"\n   * as an absence rather than a zero it has to explain.\n   */\n  earningsToday: Readonly<Record<string, AutomationAccountEarnings>>\n  /**\n   * Whether a manual run is in flight right now.\n   *\n   * A run takes tens of seconds (one upstream call per account per job, plus\n   * the scoring wait), which is far too long for the card to hold a request\n   * open. The button starts a run and the panel polls this flag instead.\n   */\n  runInProgress: boolean\n}\n\n/** The three plus one job kinds, in a stable order. */\nexport type AutomationJobKind = 'checkin' | 'tasks' | 'report' | 'streak' | 'travel' | 'compensation'\n\n/** The jobs in the order a tick runs them: report before tasks, always. */\nexport const AUTOMATION_JOB_KINDS: readonly AutomationJobKind[] = ['checkin', 'report', 'tasks', 'streak', 'travel', 'compensation']\n\n/** Reject anything that is not a job kind, so a route cannot name an unknown job. */\nexport function isAutomationJobKind(value: unknown): value is AutomationJobKind {\n  return typeof value === 'string' && (AUTOMATION_JOB_KINDS as readonly string[]).includes(value)\n}\n\ntype JobKind = AutomationJobKind\n\nconst JOB_KINDS: readonly JobKind[] = AUTOMATION_JOB_KINDS\n\n/**\n * Pick the hour list to run on: the configured one, or the default.\n *\n * An EMPTY list is treated as \"not configured\" rather than as \"never run\".\n * That distinction is the whole point: the settings schema materializes an\n * absent list into `[]` (a bare `z.array` with no `.default()`), so a config\n * that never mentioned the schedule arrives here looking exactly like one\n * deliberately set to nothing — and honouring the empty reading silently\n * disabled every job while the card still showed the switch as ON.\n *\n * A user who genuinely wants a job skipped can leave it out of the schedule\n * they save; they cannot express \"off\" with an empty array through the card\n * either way, because the card always writes a non-empty list.\n */\nfunction hoursOrDefault(configured: readonly number[] | undefined, fallback: readonly number[]): readonly number[] {\n  return configured !== undefined && configured.length > 0 ? configured : fallback\n}\n\nconst EMPTY_JOB_STATE: AutomationJobState = { ok: 0, failed: 0, credit: 0, energy: 0, claimed: 0 }\n\n/** `YYYY-MM-DD` in local time, the day key every job resets on. */\n/**\n * What the ledger gained between two snapshots, per account and in total.\n *\n * A diff rather than an absolute read: the card asks \"what did this run do\",\n * and the ledger holds the whole day, so reporting totals would re-count\n * everything an earlier run had already claimed.\n */\nfunction diffEarnings(\n  before: Record<string, AutomationAccountEarnings>,\n  after: Record<string, AutomationAccountEarnings>,\n): { credit: number; energy: number; claimed: number; accounts: Record<string, AutomationAccountGain> } {\n  const accounts: Record<string, AutomationAccountGain> = {}\n  let credit = 0\n  let energy = 0\n  let claimed = 0\n  for (const [id, entry] of Object.entries(after)) {\n    const was = before[id]\n    const gain: AutomationAccountGain = {\n      credit: entry.credit - (was?.credit ?? 0),\n      energy: entry.energy - (was?.energy ?? 0),\n      claimed: entry.claimed - (was?.claimed ?? 0),\n      checkinCredit: entry.checkinCredit - (was?.checkinCredit ?? 0),\n      bonusCredit: entry.bonusCredit - (was?.bonusCredit ?? 0),\n      travelCredit: entry.travelCredit - (was?.travelCredit ?? 0),\n      compensationCredit: entry.compensationCredit - (was?.compensationCredit ?? 0),\n    }\n    const empty = gain.credit === 0 && gain.energy === 0 && gain.claimed === 0\n      && gain.checkinCredit === 0 && gain.bonusCredit === 0 && gain.travelCredit === 0\n      && gain.compensationCredit === 0\n    // An account that gained nothing is left out entirely, so the card can\n    // list just the accounts that actually earned this run.\n    if (empty) continue\n    accounts[id] = gain\n    credit += gain.credit\n    energy += gain.energy\n    claimed += gain.claimed\n  }\n  return { credit, energy, claimed, accounts }\n}\n\n/**\n * The timezone every hour in this file is interpreted in.\n *\n * The activity windows these jobs target are defined in Beijing time, but the\n * scheduler used `getHours()`, which answers in the host machine's local zone.\n * On a machine set to anything else, \"09:00\" was 09:00 local — a check-in that\n * simply never came due. Naming the zone makes the hour mean the same instant\n * everywhere DSH runs, and is also what lets a test pin the behaviour.\n */\nexport const AUTOMATION_TIME_ZONE = 'Asia/Shanghai'\n\n/** Calendar parts of `date` in `timeZone`, all as zero-padded strings. */\nfunction zonedParts(date: Date, timeZone: string = AUTOMATION_TIME_ZONE): {\n  year: string\n  month: string\n  day: string\n  hour: string\n} {\n  const parts = new Intl.DateTimeFormat('en-CA', {\n    timeZone,\n    year: 'numeric',\n    month: '2-digit',\n    day: '2-digit',\n    hour: '2-digit',\n    hourCycle: 'h23',\n  }).formatToParts(date)\n  const pick = (type: string): string => parts.find(part => part.type === type)?.value ?? '00'\n  return { year: pick('year'), month: pick('month'), day: pick('day'), hour: pick('hour') }\n}\n\nexport function dayKey(date: Date, timeZone: string = AUTOMATION_TIME_ZONE): string {\n  const { year, month, day } = zonedParts(date, timeZone)\n  return `${year}-${month}-${day}`\n}\n\n/**\n * The scheduled SLOT `date` falls in, as `YYYY-MM-DDTHH`.\n *\n * The per-job run guard keys on this instead of the date, so a job configured\n * for several hours runs in each of them while a second tick inside the same\n * hour is still refused.\n */\nexport function slotKey(date: Date, timeZone: string = AUTOMATION_TIME_ZONE): string {\n  const { hour } = zonedParts(date, timeZone)\n  return `${dayKey(date, timeZone)}T${hour}`\n}\n\n/**\n * Whether `now`'s local hour is one of `hours`.\n *\n * The reference panel computes a `nextFire` instant and sleeps until it; this\n * loop instead wakes every minute and asks \"is any job due now\". Both fire at\n * the top of a configured hour, but the polling form cannot miss a slot to a\n * suspended process — a laptop that slept through 10:00 still runs the job the\n * moment it wakes, on the same day.\n */\nexport function isFireHour(now: Date, hours: readonly number[]): boolean {\n  const { hour } = zonedParts(now)\n  return hours.includes(Number(hour))\n}\n\n/** Whether this account may be used: not switched off, not cooling. */\nfunction eligible(account: WorkBuddyAccount, now: number): boolean {\n  if (account.cooldownUntilMs > now) return false\n  // The growth system is CN-only; a global account has no task centre at all.\n  if (regionOf(account.credential.domain) === 'global') return false\n  return true\n}\n\nconst sleep = (ms: number): Promise<void> => new Promise(resolve => { setTimeout(resolve, ms) })\n\n/**\n * The points automation.\n *\n * Owns a single timer loop. Construction is inert — nothing runs until\n * {@link start}, and {@link stop} is idempotent so a plugin teardown that fires\n * twice is harmless.\n */\nexport class WorkBuddyScheduler {\n  private readonly pool: WorkBuddyAccountPool\n\n  private readonly client: WorkBuddyUpstreamClient\n\n  private readonly logger: SchedulerLogger\n\n  private readonly now: () => Date\n\n  private readonly delayMs: number\n\n  /**\n   * How long to wait for event scoring before re-reading the task list.\n   * Tests set 0 so a pass does not spend nine real seconds per account.\n   */\n  private readonly eventScoreWaitMs: number\n\n  /**\n   * Gap between two expert summon chains.\n   * Tests set 0 so a pass does not spend six real seconds per expert.\n   */\n  private readonly expertGapMs: number\n\n  private enabled: boolean\n\n  private checkinHours: readonly number[]\n\n  private taskHours: readonly number[]\n\n  private reportHours: readonly number[]\n\n  private streakHours: readonly number[]\n  private travelHours: readonly number[]\n  private compensationHours: readonly number[]\n\n  private timer: NodeJS.Timeout | undefined\n\n  private running = false\n\n  /** Guards against a slow run overlapping the next tick. */\n  private busy = false\n  /** True while a manual run is in flight, so the card can poll it. */\n  private runInFlight = false\n\n  /**\n   * Set once {@link stop} is called.\n   *\n   * Deliberately false before `start`: the loop is not running yet, but a\n   * manual `tick` must still work. `stop` is what makes a run abandon the\n   * accounts it has not reached yet.\n   */\n  private stopped = false\n\n  private readonly states: Record<JobKind, AutomationJobState> = {\n    checkin: { ...EMPTY_JOB_STATE },\n    report: { ...EMPTY_JOB_STATE },\n    tasks: { ...EMPTY_JOB_STATE },\n    streak: { ...EMPTY_JOB_STATE },\n    travel: { ...EMPTY_JOB_STATE },\n    compensation: { ...EMPTY_JOB_STATE },\n  }\n\n  private claimableSeen = 0\n  /**\n   * Credits/energy/tasks earned per account TODAY, keyed by account id.\n   *\n   * Cleared whenever the day key rolls over, so the card always answers\n   * \"what did the automation get for THIS account today\".\n   */\n  private earnings = new Map<string, AutomationAccountEarnings>()\n  /** Day key the counters above belong to. */\n  private earningsDate = ''\n  /** Host hooks that persist the ledger across restarts. */\n  private readonly loadEarnings: (() => AutomationLedger | undefined) | undefined\n  private saveEarningsFn: ((ledger: AutomationLedger) => void | Promise<void>) | undefined\n\n  constructor(pool: WorkBuddyAccountPool, client: WorkBuddyUpstreamClient, options: AutomationOptions = {}) {\n    this.pool = pool\n    this.client = client\n    this.logger = options.logger ?? {}\n    this.now = options.now ?? (() => new Date())\n    this.delayMs = options.accountDelayMs ?? AUTOMATION_ACCOUNT_DELAY_MS\n    this.eventScoreWaitMs = options.eventScoreWaitMs ?? EVENT_SCORE_WAIT_MS\n    this.expertGapMs = options.expertGapMs ?? EXPERT_SUMMON_GAP_MS\n    this.loadEarnings = options.loadEarnings\n    this.saveEarningsFn = options.saveEarnings\n    // Restore today's ledger, discarding one from an earlier day: the counters\n    // answer \"what did the automation get TODAY\", so yesterday's totals must not\n    // be presented as today's.\n    const restored = options.loadEarnings?.()\n    const today = dayKey(this.now())\n    if (restored !== undefined && restored.date === today) {\n      for (const [id, entry] of Object.entries(restored.accounts)) this.earnings.set(id, entry)\n      this.earningsDate = today\n    }\n    this.enabled = options.enabled ?? false\n    this.checkinHours = hoursOrDefault(options.checkinHours, DEFAULT_AUTOMATION_HOURS.checkin)\n    this.reportHours = hoursOrDefault(options.reportHours, DEFAULT_AUTOMATION_HOURS.report)\n    this.taskHours = hoursOrDefault(options.taskHours, DEFAULT_AUTOMATION_HOURS.tasks)\n    this.streakHours = hoursOrDefault(options.streakHours, DEFAULT_AUTOMATION_HOURS.streak)\n    // Two passes, not one: a trip loop needs a departure AND a collection, and\n    // a cat sent out at the single pass of the day would sit there until\n    // tomorrow. Morning out, evening back — the reference panel settled on the\n    // same pair for the same reason.\n    this.travelHours = hoursOrDefault(options.travelHours, DEFAULT_AUTOMATION_HOURS.travel)\n    // Late in the morning, on purpose: the compensation offer appears when the\n    // outage is announced, so an early slot would find nothing. By mid-morning a\n    // fresh offer is live and the deadline (typically days out) still has room.\n    this.compensationHours = hoursOrDefault(options.compensationHours, DEFAULT_AUTOMATION_HOURS.compensation)\n  }\n\n  /** Apply a new configuration; safe to call while running. */\n  /**\n   * Install the persistence hook once the host settings service is available.\n   *\n   * Separate from the constructor because the scheduler is built with the pool,\n   * long before the settings section exists; a ledger written before that point\n   * would have nowhere to go.\n   */\n  setEarningsPersistence(save: (ledger: AutomationLedger) => void | Promise<void>): void {\n    this.saveEarningsFn = save\n  }\n\n  /**\n   * Fold a previously persisted ledger back in, when it belongs to today.\n   *\n   * Used after the settings document becomes readable, which happens after\n   * construction; a ledger from an earlier day is ignored so the counters never\n   * claim yesterday as today.\n   */\n  applyEarningsLedger(ledger: AutomationLedger): void {\n    const today = dayKey(this.now())\n    if (ledger.date !== today) return\n    for (const [id, entry] of Object.entries(ledger.accounts)) this.earnings.set(id, entry)\n    this.earningsDate = today\n  }\n\n  applyConfig(options: AutomationOptions): void {\n    if (options.enabled !== undefined) this.enabled = options.enabled\n    // Each hour list falls back to its default when it arrives EMPTY, for the\n    // same reason the constructor does: an absent list is materialized as `[]`\n    // by the settings schema, so a plain `!== undefined` test adopted the empty\n    // array and the constructor defaults could never apply. That is how a\n    // switched-ON automation ended up with no runnable hour at all.\n    if (options.checkinHours !== undefined) {\n      this.checkinHours = hoursOrDefault(options.checkinHours, DEFAULT_AUTOMATION_HOURS.checkin)\n    }\n    if (options.reportHours !== undefined) {\n      this.reportHours = hoursOrDefault(options.reportHours, DEFAULT_AUTOMATION_HOURS.report)\n    }\n    if (options.taskHours !== undefined) {\n      this.taskHours = hoursOrDefault(options.taskHours, DEFAULT_AUTOMATION_HOURS.tasks)\n    }\n    if (options.streakHours !== undefined) {\n      this.streakHours = hoursOrDefault(options.streakHours, DEFAULT_AUTOMATION_HOURS.streak)\n    }\n    if (options.travelHours !== undefined) {\n      this.travelHours = hoursOrDefault(options.travelHours, DEFAULT_AUTOMATION_HOURS.travel)\n    }\n    if (options.compensationHours !== undefined) {\n      this.compensationHours = hoursOrDefault(options.compensationHours, DEFAULT_AUTOMATION_HOURS.compensation)\n    }\n  }\n\n  /** Hours for one job, used by the loop and the status document. */\n  private hoursOf(kind: JobKind): readonly number[] {\n    switch (kind) {\n      case 'checkin': return this.checkinHours\n      case 'report': return this.reportHours\n      case 'tasks': return this.taskHours\n      case 'streak': return this.streakHours\n      case 'travel': return this.travelHours\n      case 'compensation': return this.compensationHours\n    }\n  }\n\n  /** Start the loop. Idempotent. */\n  start(): void {\n    if (this.timer !== undefined) return\n    this.stopped = false\n    this.running = true\n    // Unref so the plugin never keeps a host process alive on its own.\n    this.timer = setInterval(() => { void this.tick() }, AUTOMATION_TICK_MS)\n    this.timer.unref?.()\n  }\n\n  /** Stop the loop. Idempotent, and safe before `start`. */\n  stop(): void {\n    this.stopped = true\n    this.running = false\n    if (this.timer !== undefined) {\n      clearInterval(this.timer)\n      this.timer = undefined\n    }\n  }\n\n  /** Snapshot for the status document. */\n  /**\n   * Run one job immediately, regardless of the clock.\n   *\n   * Exists so the automation can be verified from the card without waiting for\n   * its hour. A manual run is recorded exactly like a scheduled one, so the\n   * timer will not repeat it later the same day: every job is idempotent, but a\n   * second pass would still be wasted upstream calls.\n   *\n   * `force` ignores the already-ran-today guard, which is what pressing the\n   * button a second time means.\n   */\n  async runNow(kind: AutomationJobKind, force = false): Promise<AutomationJobState> {\n    const today = dayKey(this.now())\n    const state = this.states[kind]\n    // Throttle on the START hour, not on the schedule ledger: a manual run is\n    // an explicit \"do it now\", so a second press inside the same hour is a\n    // no-op, but it never pretends a scheduled slot ran.\n    if (!force && state.lastFiredHour === slotKey(this.now())) return { ...state }\n    this.busy = true\n    try {\n      // No `consumedSlot`: a manual run does not spend a scheduled candidate.\n      await this.runJob(kind, today)\n    } finally {\n      this.busy = false\n    }\n    return { ...this.states[kind] }\n  }\n\n  /**\n   * Run every job once, in the scheduled order.\n   *\n   * Order matters and is not configurable: the activity report has to land\n   * before the task pass reads task progress, or the pass sees counters the\n   * report would have moved. This is what the card's single button calls.\n   */\n  /**\n   * Start a full pass in the background and return immediately.\n   *\n   * A pass takes tens of seconds - one upstream round trip per account per job,\n   * plus the scoring wait - which is far too long to hold the card request open:\n   * the browser or the host web server would time out, and the user would see\n   * a hung button for a run that is actually working.\n   *\n   * Returns whether a run started. A second call while one is in flight is\n   * ignored rather than queued: pressing the button twice means hurry up, and\n   * the run already under way covers it.\n   */\n  startRunAll(): boolean {\n    if (this.runInFlight) return false\n    this.runInFlight = true\n    void this.runAll()\n      .catch((error: unknown) => {\n        this.logger.warn?.('dsh-xdpool automation run failed:', error)\n      })\n      .finally(() => { this.runInFlight = false })\n    return true\n  }\n\n  async runAll(): Promise<AutomationRunSummary> {\n    const today = dayKey(this.now())\n    const before = this.earningsSnapshot()\n    let okCount = 0\n    let failed = 0\n    let jobsRun = 0\n    for (const kind of JOB_KINDS) {\n      // Runs EVERY job, including one whose hour list is empty: the button\n      // is an explicit \"do everything now\", and a job with no schedule is\n      // still one the user can want executed on demand.\n      //\n      // No `consumedSlot` is passed, deliberately. A manual pass is an EXTRA\n      // run, not a substitute for the schedule: consuming the day's remaining\n      // candidates here would mean one button press cancels today's 21:00 cat\n      // trip. The scheduled hours still fire on their own; this only adds a\n      // run on top. (The trade-off is that a manual pass does not suppress the\n      // next automated one — which is the safer direction, and each job is\n      // idempotent anyway.)\n      jobsRun += 1\n      this.busy = true\n      try {\n        await this.runJob(kind, today)\n      } finally {\n        this.busy = false\n      }\n      okCount += this.states[kind].ok\n      failed += this.states[kind].failed\n    }\n    // Diff the ledger against the pre-run snapshot. Summing per-job state\n    // would mix one job's counters into another's, and reporting the\n    // absolute totals would re-count everything claimed earlier today.\n    const after = this.earningsSnapshot()\n    const gained = diffEarnings(before, after)\n    return {\n      jobsRun,\n      okCount,\n      failed,\n      credit: gained.credit,\n      energy: gained.energy,\n      claimed: gained.claimed,\n      accounts: gained.accounts,\n    }\n  }\n\n  status(): AutomationStatus {\n    const jobs = {} as AutomationStatus['jobs']\n    for (const kind of JOB_KINDS) jobs[kind] = { ...this.states[kind] }\n    return {\n      enabled: this.enabled,\n      running: this.running,\n      checkinHours: this.checkinHours,\n      taskHours: this.taskHours,\n      reportHours: this.reportHours,\n      streakHours: this.streakHours,\n      travelHours: this.travelHours,\n      compensationHours: this.compensationHours,\n      jobs,\n      claimableSeen: this.claimableSeen,\n      earningsToday: this.earningsSnapshot(),\n      runInProgress: this.runInFlight, \n    }\n  }\n\n  /**\n   * One poll: run every due job, serially.\n   *\n   * Serial by design — the jobs share the same accounts and the upstream\n   * rate-limits per account, so overlapping passes would only trip that limit.\n   * A job that throws is recorded and the loop continues.\n   */\n  /**\n   * Whether `kind` is due at `now`: its earliest configured hour has passed in\n   * the scheduling timezone, and no hour of today has been consumed yet.\n   *\n   * Hours are consumed per SLOT (one entry per configured hour), so a job with\n   * two hours still runs twice a day — but a job whose hour passed while DSH was\n   * closed runs immediately on the next tick instead of waiting for tomorrow.\n   */\n  /**\n   * The configured slot `kind` should consume at `now`, or undefined when none.\n   *\n   * Returns the SLOT STRING (not a boolean) because the caller must record the\n   * same value it acted on. Returning a boolean was the original bug's enabler:\n   * the tick asked \"is it due\", then `runJob` independently wrote \"what time is\n   * it now\" — and those two answers were almost never equal.\n   *\n   * CATCH-UP semantics are deliberate: a candidate fires once its hour has\n   * PASSED and its slot is still unconsumed, so a laptop that slept through\n   * 10:00 still runs the job when it wakes, on the same day.\n   *\n   * The EARLIEST unconsumed candidate wins, which is what keeps a two-hour job\n   * (`travelHours: [9, 21]`) whole: consuming the earliest due slot leaves the\n   * later one for its own hour.\n   */\n  private dueSlot(kind: JobKind, now: Date): string | undefined {\n    const hours = this.hoursOf(kind)\n    if (hours.length === 0) return undefined\n    const current = Number(zonedParts(now).hour)\n    const today = dayKey(now)\n    const fired = this.firedSlotsOf(kind)\n    // Ordered by configured hour, so the first match is the earliest due one.\n    for (const candidate of [...hours].sort((a, b) => a - b)) {\n      if (candidate > current) break\n      const slot = `${today}T${String(candidate).padStart(2, '0')}`\n      if (!fired.has(slot)) return slot\n    }\n    return undefined\n  }\n\n  /** Today's consumed slots for one job, as a set. */\n  private firedSlotsOf(kind: JobKind): Set<string> {\n    const state = this.states[kind]\n    const stored = state.firedSlots\n    if (stored === undefined) return new Set<string>()\n    // Drop entries from earlier days as we read: the set only ever answers\n    // \"has TODAY's candidate run\", so carrying yesterday's keys forward would\n    // grow it without bound and never change an answer.\n    const today = dayKey(this.now())\n    return new Set(stored.filter(slot => slot.startsWith(`${today}T`)))\n  }\n\n  /** Record one consumed slot on a job's state. */\n  private consumeSlot(kind: JobKind, slot: string): void {\n    const state = this.states[kind]\n    const today = dayKey(this.now())\n    const next = new Set([...this.firedSlotsOf(kind), slot])\n    // Persist in a stable order so the status document (and any future\n    // persistence of it) does not churn between reads.\n    state.firedSlots = [...next].filter(entry => entry.startsWith(`${today}T`)).sort()\n  }\n\n  private async tick(): Promise<void> {\n    if (!this.enabled || this.stopped || this.busy) return\n    this.busy = true\n    try {\n      const now = this.now()\n      const slot = slotKey(now)\n      const today = dayKey(now)\n      for (const kind of JOB_KINDS) {\n        if (this.stopped) return\n        // Throttle only: never start the same job twice inside one clock hour.\n        // This is NOT the schedule ledger — that is `firedSlots`, checked by\n        // `dueSlot` below. Tying the throttle to the ledger is what let a\n        // catch-up run consume a slot it had not actually been scheduled for.\n        if (this.states[kind].lastFiredHour === slot) continue\n        // CATCH-UP: run if the configured hour has already PASSED and that\n        // slot is still unconsumed. The old equality test (`hour === configured`)\n        // silently skipped the day whenever DSH was not running at that exact\n        // hour — a 09:00 check-in never ran if the app started at 10:00. Asking\n        // \"has the hour passed, and is that slot still unspent\" makes a missed\n        // schedule self-heal on the next tick, which is what a laptop that\n        // slept through the hour needs.\n        const consumed = this.dueSlot(kind, now)\n        if (consumed === undefined) continue\n        await this.runJob(kind, today, consumed)\n      }\n    } catch (error: unknown) {\n      // A defect in the loop itself must not kill the timer.\n      this.logger.warn?.('dsh-xdpool automation tick failed:', error)\n    } finally {\n      this.busy = false\n    }\n  }\n\n  /** Run one job against every eligible account and record the outcome. */\n  /**\n   * Add one account's take to today's counters, resetting first if the day\n   * rolled over. Called from the task pass, which is the only job that earns.\n   */\n  /**\n   * Today's per-account earnings, as a plain object for the status document.\n   *\n   * Rolls the day first so a status read just after midnight does not report\n   * yesterday's totals under today's date.\n   */\n  private earningsSnapshot(): Record<string, AutomationAccountEarnings> {\n    this.rollEarnings(dayKey(this.now()))\n    const out: Record<string, AutomationAccountEarnings> = {}\n    for (const [id, entry] of this.earnings) out[id] = { ...entry }\n    return out\n  }\n\n  /**\n   * Add one account take to today counters, resetting first if the day rolled\n   * over. Every source is tracked separately so the card can show what earned\n   * what, rather than one opaque total.\n   */\n  private recordEarnings(\n    accountId: string,\n    today: string,\n    delta: Partial<Omit<AutomationAccountEarnings, 'date'>>,\n  ): void {\n    this.rollEarnings(today)\n    const credit = delta.credit ?? 0\n    const energy = delta.energy ?? 0\n    const claimed = delta.claimed ?? 0\n    const checkinCredit = delta.checkinCredit ?? 0\n    const bonusCredit = delta.bonusCredit ?? 0\n    const travelCredit = delta.travelCredit ?? 0\n    const compensationCredit = delta.compensationCredit ?? 0\n    const empty = credit === 0 && energy === 0 && claimed === 0\n      && checkinCredit === 0 && bonusCredit === 0 && travelCredit === 0\n      && compensationCredit === 0\n    if (empty) return\n    const existing = this.earnings.get(accountId)\n    this.earnings.set(accountId, {\n      credit: (existing?.credit ?? 0) + credit,\n      energy: (existing?.energy ?? 0) + energy,\n      claimed: (existing?.claimed ?? 0) + claimed,\n      checkinCredit: (existing?.checkinCredit ?? 0) + checkinCredit,\n      bonusCredit: (existing?.bonusCredit ?? 0) + bonusCredit,\n      travelCredit: (existing?.travelCredit ?? 0) + travelCredit,\n      compensationCredit: (existing?.compensationCredit ?? 0) + compensationCredit,\n      date: today,\n    })\n    // Persisted on every write: a restart mid-day must not wipe what was\n    // already earned, or the card would show nothing for real rewards.\n    this.persistEarnings()\n  }\n\n  /** Clear the per-account counters when the local day changes. */\n  private rollEarnings(today: string): void {\n    if (this.earningsDate === today) return\n    this.earningsDate = today\n    this.earnings.clear()\n    this.claimableSeen = 0\n    this.persistEarnings()\n  }\n\n  /**\n   * Write the ledger through the host hook, when one was supplied.\n   *\n   * Best effort on purpose: a failed save must never abort a run that has\n   * already collected rewards, and the in-memory ledger keeps serving the card\n   * for the rest of the session either way.\n   */\n  private persistEarnings(): void {\n    if (this.saveEarningsFn === undefined) return\n    const accounts: Record<string, AutomationAccountEarnings> = {}\n    for (const [id, entry] of this.earnings) accounts[id] = entry\n    const ledger = { date: this.earningsDate, accounts }\n    try {\n      // The hook may be async (the host-side settings write is). A `try` around a\n      // call that is not awaited catches only SYNCHRONOUS throws — an async\n      // rejection escapes as an unhandled rejection, and the host installs\n      // `installFailLoud`, which turns any unhandled rejection into exit(1). So a\n      // failed save would take the whole process down instead of being logged.\n      // Attaching the handler here (rather than awaiting) keeps this call site\n      // synchronous, which is what the callers — `rollEarnings`,\n      // `recordEarnings`, `status` — all assume.\n      const saved = this.saveEarningsFn(ledger)\n      if (saved !== undefined && typeof saved.then === 'function') {\n        void saved.then(undefined, (error: unknown) => {\n          this.logger.warn?.('dsh-xdpool: could not persist automation earnings:', error)\n        })\n      }\n    } catch (error: unknown) {\n      this.logger.warn?.('dsh-xdpool: could not persist automation earnings:', error)\n    }\n  }\n\n\n  /**\n   * Run one job against every eligible account and record the outcome.\n   *\n   * `consumedSlot` is the configured slot this run spends (`dueSlot`'s answer).\n   * It is passed IN rather than recomputed here so the value recorded is exactly\n   * the value the schedule decided on — the defect this replaces wrote\n   * `slotKey(now)` instead, i.e. the clock time the run finished at, which\n   * almost never equals the configured candidate the gate had compared against.\n   *\n   * The task job runs in TWO passes. The first sends the event chains that light\n   * up client-scored tasks; the second collects rewards. They are separate\n   * because scoring lands asynchronously — a chain sent and claimed within the\n   * same breath finds the task still un-scored — and because sending is fast\n   * while claiming wants the whole pool to have been lit up first. Splitting\n   * them costs one shared wait instead of one wait per account.\n   */\n  private async runJob(kind: JobKind, today: string, consumedSlot?: string): Promise<void> {\n    const accountWord = kind === 'report' ? 'report' : kind\n    let ok = 0\n    let failed = 0\n    let credit = 0\n    let energy = 0\n    let claimed = 0\n    const detail: string[] = []\n    let progressNote: string | undefined\n    \n    const accounts = this.accountsInOrder()\n\n    // Pass 1 (tasks only): light up the client-scored tasks for EVERY account\n    // before claiming any of them. Claiming inside this loop would find each\n    // chain still unscored, because scoring lands a few seconds later.\n    if (kind === 'tasks') await this.sendEventChains(accounts)\n\n    for (let index = 0; index < accounts.length; index++) {\n      if (this.stopped) break\n      const account = accounts[index]\n      if (account === undefined) continue\n      try {\n        switch (kind) {\n          case 'checkin': {\n              try {\n                const claim = await this.client.claimDailyCheckin(account.credential)\n                // Check-in pays credits, so it belongs in the earnings ledger. A\n                // repeat check-in pays 0, which records as a no-op.\n                this.recordEarnings(account.id, today, { checkinCredit: claim.credit })\n                if (claim.credit > 0) {\n                if (claim.credit > 0) detail.push(`签到 +${claim.credit}`)\n                  this.logger.info?.(`automation checkin ${account.label}: +${claim.credit} credit`)\n                }\n              } catch (error: unknown) {\n                // \"Already checked in today\" arrives as an error from the upstream\n                // but is an idempotent success: the day is already collected.\n                // Counting it as a failure would make a healthy account look\n                // broken and would inflate the run summary.\n                if (!isAlreadyCheckin(error)) throw error\n                this.logger.info?.(`automation checkin ${account.label}: already done today`)\n              }\n              break\n            }\n          case 'report': {\n            const days = await this.reportOne(account)\n            this.logger.info?.(`automation report ${account.label}: streak days=${days}`)\n            break\n          }\n          case 'tasks': {\n            const result = await this.runTasks(account)\n            credit += result.credit\n            energy += result.energy\n            claimed += result.claimed\n            detail.push(...result.titles)\n            this.claimableSeen += result.claimableCount\n            this.recordEarnings(account.id, today, { credit: result.credit, energy: result.energy, claimed: result.claimed })\n            this.logger.info?.(\n              `automation tasks ${account.label}: ${result.claimed} claimed (+${result.credit} credit, +${result.energy} energy, ${result.claimableCount} claimable seen)`,\n            )\n            break\n          }\n          case 'streak': {\n            const progress = await this.redeemStreak(account)\n            if (progress !== undefined) progressNote = progress\n            break\n          }\n          case 'travel': {\n            await this.runTravel(account)\n            break\n          }\n          case 'compensation': {\n            try {\n              const outcome = await this.runCompensation(account)\n              // Only an offer that was actually collectable counts as earnings;\n              // \"no offer right now\" is a successful no-op, not a failure.\n              if (outcome.credit > 0) {\n                detail.push(`补偿 +${outcome.credit}`)\n                this.logger.info?.(`automation compensation ${account.label}: +${outcome.credit} credit`)\n              }\n            } catch (error: unknown) {\n              // No offer for this account is the normal state for most of the\n              // time, and upstream reports it as an error. Treating that as a\n              // failure would make every healthy account look broken.\n              if (!isNoCompensation(error)) throw error\n              this.logger.info?.(`automation compensation ${account.label}: no offer to collect`)\n            }\n            break\n          }\n\n        }\n        ok++\n      } catch (error: unknown) {\n        // One account failing never stops the pass: a dead token, a 429 or a\n        // malformed payload on one account must not cost the other accounts\n        // their daily points.\n        failed++\n        this.logger.warn?.(`automation ${accountWord} ${account.label} failed:`, error)\n      }\n      // Serial spacing, but never sleep after the final account.\n      if (index < accounts.length - 1 && this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n    }\n\n    const state = this.states[kind]\n    // Three separate facts, three separate fields — collapsing any two of them\n    // is what produced the \"runs every hour\" defect:\n    //\n    //   firedSlots    what the SCHEDULE spent (configured hours, a set)\n    //   lastFiredHour when the run STARTED (throttle only)\n    //   lastRunAtMs   when the run FINISHED (displayed on the card)\n    //\n    // A manual run passes no `consumedSlot`; it still stamps `lastFiredHour`\n    // and `lastRunAtMs`, but it does NOT silently spend a scheduled slot it was\n    // never meant to consume — pressing \"run now\" at 10:35 must not cancel the\n    // 21:00 cat trip.\n    if (consumedSlot !== undefined) this.consumeSlot(kind, consumedSlot)\n    state.lastFiredHour = slotKey(this.now())\n    state.lastRunDate = today\n    state.lastRunAtMs = this.now().getTime()\n    state.ok = ok\n    state.failed = failed\n    state.credit = credit\n    state.energy = energy\n    state.claimed = claimed\n    state.message = this.summarise(kind, ok, failed, claimed, credit, energy)\n    state.detail = detail\n    state.progress = progressNote\n    this.logger.info?.(`automation ${accountWord}: ${state.message}`)\n  }\n\n  /** Compose the one-line summary shown on the card. */\n  private summarise(\n    kind: JobKind,\n    ok: number,\n    failed: number,\n    claimed: number,\n    credit: number,\n    energy: number,\n  ): string {\n    if (kind === 'tasks') {\n      const suffix = failed > 0 ? `, ${failed} failed` : ''\n      return `${ok} accounts, ${claimed} tasks claimed (+${credit} credit, +${energy} energy)${suffix}`\n    }\n    const suffix = failed > 0 ? `, ${failed} failed` : ''\n    return `${ok} accounts ok${suffix}`\n  }\n\n  /**\n   * Accounts to run against, in pool order.\n   *\n   * Disabled accounts are excluded here rather than filtered by the caller so a\n   * card switch takes effect on the next pass without any event plumbing.\n   */\n  private accountsInOrder(): WorkBuddyAccount[] {\n    const now = Date.now()\n    return this.pool.list().filter(account => {\n      if (this.pool.isDisabled(account.id)) return false\n      return eligible(account, now)\n    })\n  }\n\n  /**\n   * Send one activity report, then verify it landed.\n   *\n   * The upstream answers 200 even when it drops the event, so the streak is\n   * read back as the oracle: `days > 0` means it counted. A failed read-back is\n   * logged and treated as a suspicious result, never as a retry — the report is\n   * idempotent per day, and hammering it is exactly what the one-a-day quota\n   * exists to avoid.\n   */\n  private async reportOne(account: WorkBuddyAccount): Promise<number> {\n    await this.client.reportActivity(account.credential)\n    try {\n      const days = await this.client.growthStreakDays(account.credential)\n      if (days === 0) {\n        // Two innocent causes: a brand-new account whose streak is genuinely 0,\n        // and the scoring lag - the counter is written asynchronously, so an\n        // immediate read-back can still see the previous value (observed live\n        // against one live account: 0 right after the report, 1 a minute later).\n        // A later pass settles it; retrying here would only burn the quota.\n        this.logger.warn?.(`automation report ${account.label}: streak days=0 right after report (new account or scoring lag?)`)\n      }\n      return days\n    } catch (error: unknown) {\n      this.logger.warn?.(`automation report ${account.label}: streak read-back failed:`, error)\n      return -1\n    }\n  }\n  private async sendEventChains(accounts: readonly WorkBuddyAccount[]): Promise<void> {\n    let sentAnything = false\n    for (const account of accounts) {\n      if (this.stopped) return\n      let tasks: readonly WorkBuddyTask[]\n      try {\n        tasks = await this.client.listTasks(account.credential)\n      } catch (error: unknown) {\n        // A read failure here is not fatal: the claim pass will read again and\n        // record the failure there.\n        this.logger.warn?.(`automation events ${account.label}: list failed:`, error)\n        continue\n      }\n      // Every task still short of its target is a candidate. The chains build\n      // their own ids, so there is nothing to cache between accounts.\n      const pending = tasks.filter(task =>\n        task.taskCode in EVENT_CHAIN_BUILDERS && !task.claimable && !task.locked)\n      for (const task of pending) {\n        if (this.stopped) return\n        let chains: readonly TaskEventChain[]\n        try {\n          chains = await this.chainsFor(task, account.credential)\n        } catch (error: unknown) {\n          this.logger.warn?.(`automation events ${account.label}: ${task.taskCode} could not be built:`, error)\n          continue\n        }\n        for (const chain of chains) {\n          if (this.stopped) return\n          try {\n            await this.sendChain(account.credential, chain)\n            this.logger.info?.(`automation events ${account.label}: ${task.taskCode} chain sent`)\n            sentAnything = true\n          } catch (error: unknown) {\n            // One chain failing must not stop the others or the claim pass.\n            this.logger.warn?.(`automation events ${account.label}: ${task.taskCode} failed:`, error)\n            break\n          }\n          if (this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n        }\n      }\n    }\n    // Scoring lands a few seconds after the events. Waiting it out here is what\n    // lets the claim pass that follows collect the reward on THIS run instead of\n    // leaving it for a later one. Paid once for the pool.\n    if (sentAnything && this.eventScoreWaitMs > 0 && !this.stopped) await sleep(this.eventScoreWaitMs)\n  }\n\n  /**\n   * Send one chain on the channel it was built for.\n   *\n   * The transport is not a detail of the sender: the scorer keys different\n   * tasks to different fingerprint families, so a web-scored event posted as a\n   * desktop event is accepted and then ignored.\n   */\n  private async sendChain(credential: WorkBuddyCredential, chain: TaskEventChain): Promise<void> {\n    if (chain.transport === 'web') {\n      const web = chain.web\n      if (web === undefined) throw new Error('web chain without a web event')\n      await this.client.reportWebEvent(credential, web.eventCode, web.pageUrl, web.elementId, web.elementName)\n      return\n    }\n    await this.client.reportDesktopEvents(credential, chain.events ?? [])\n  }\n\n  /**\n   * Build every chain that scores one task.\n   *\n   * Most tasks need a single chain; `template_5` needs five, because the scorer\n   * counts distinct `template_used` events rather than a boolean. The two tasks\n   * that join a conversation (skill, expert) open a real one first, which is why\n   * this is async.\n   */\n  private async chainsFor(task: WorkBuddyTask, credential: WorkBuddyCredential): Promise<readonly TaskEventChain[]> {\n    switch (task.taskCode) {\n      case 'Buddy_App':\n      case 'Buddy_App_QQ':\n        return [buddyAppChain()]\n      case 'create_canvas':\n        return [canvasChain()]\n      case 'automation_1':\n        return [automationChain()]\n      case 'RichMeow_Chat':\n        return [chatChain()]\n      case 'playbook_prompt':\n        return [playbookChain()]\n      case 'template_5':\n        return templateChains()\n      case 'Hp_Appearance':\n        // The event alone is not the whole chain: the client first stores the\n        // selected skin, then reports the apply on the way out of settings.\n        await this.client.setAppearanceTheme(credential, APPEARANCE_THEME_KEY)\n        if (this.delayMs > 0 && !this.stopped) await sleep(2_000)\n        return [appearanceChain()]\n      case 'Library_read':\n        return [libraryReadChain()]\n      case 'skill_1': {\n        const chat = await this.client.openConversation(credential)\n        if (chat === undefined) throw new Error('skill_1: no server conversation')\n        return [skillChain(chat.conversationId, chat.requestId)]\n      }\n      case 'expert_5':\n        return this.expertChains(credential, 'agent', task)\n      case 'Expert_team_use_3':\n        return this.expertChains(credential, 'team', task)\n      case 'Expert_lighthouse':\n        return this.lighthouseChains(credential)\n      default:\n        return []\n    }\n  }\n\n  /**\n   * The summon-and-use chains for the expert tasks.\n   *\n   * Two steps per expert, and both are load-bearing: the summon events alone are\n   * impressions, and a use event on its own scores nothing because the scorer\n   * looks the conversation up. Only a real chat with `X-Expert-Id` produces an\n   * id it will accept.\n   */\n  private async expertChains(\n    credential: WorkBuddyCredential,\n    expertType: 'agent' | 'team',\n    task: WorkBuddyTask,\n  ): Promise<readonly TaskEventChain[]> {\n    // Only as many as are still missing, so a replay of the pass does not\n    // re-chat experts the account already used.\n    const needed = Math.max(0, task.target - task.current)\n    if (needed === 0) return []\n    const experts = await this.client.marketExpertList(credential, expertType)\n    const out: TaskEventChain[] = []\n    for (const expert of experts) {\n      if (out.length >= needed) break\n      if (this.stopped) break\n      try {\n        await this.client.reportDesktopEvents(credential, expertSummonEvents(expert))\n        if (this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n        const chat = await this.client.openConversation(credential, expert.expertId)\n        if (chat === undefined) continue\n        out.push({\n          transport: 'desktop',\n          events: [\n            ...expertChatEvents(expert, chat.conversationId, chat.requestId),\n            expertActualUseEvent(expert, chat.conversationId, chat.requestId),\n          ],\n        })\n      } catch (error: unknown) {\n        this.logger.warn?.(`automation events expert ${expert.expertId}:`, error)\n      }\n      // Space the chains out: back-to-back uses collapse into one as far as the\n      // scorer is concerned, which is what left this task one short.\n      if (this.expertGapMs > 0 && !this.stopped) await sleep(this.expertGapMs)\n    }\n    return out\n  }\n\n  /**\n   * The 腾讯轻量云 expert chain.\n   *\n   * Structurally the same as the expert task, with two differences the scorer\n   * checks: `agent_task_created` has to name the expert, and the use event has\n   * to report `mode: 'LOCAL'` with an empty type and zero cost — that is what\n   * the lighthouse criterion looks for.\n   */\n  private async lighthouseChains(credential: WorkBuddyCredential): Promise<readonly TaskEventChain[]> {\n    let expert = LIGHTHOUSE_EXPERT\n    // Prefer the marketplace's own record when it lists this expert, so the\n    // version and title come from the server rather than this constant.\n    try {\n      const listed = await this.client.marketExpertList(credential, 'agent')\n      const found = listed.find(item => item.expertId === LIGHTHOUSE_EXPERT_ID)\n      if (found !== undefined) expert = found\n    } catch (error: unknown) {\n      this.logger.warn?.('automation events lighthouse list:', error)\n    }\n    await this.client.reportDesktopEvents(credential, expertSummonEvents(expert))\n    if (this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n    const chat = await this.client.openConversation(credential, expert.expertId)\n    if (chat === undefined) throw new Error('Expert_lighthouse: no server conversation')\n    const use = expertActualUseEvent(expert, chat.conversationId, chat.requestId, 'LOCAL')\n    // Align with the real sample: the lighthouse expert reports no type and no\n    // cost, and the scorer matches on that shape.\n    use['type'] = ''\n    use['cost'] = 0\n    return [{\n      transport: 'desktop',\n      events: [...expertChatEvents(expert, chat.conversationId, chat.requestId), use],\n    }]\n  }\n\n\n  /**\n   * The task-centre pass for one account.\n   *\n   * Order matters: enrich first (enrol in everything open), then claim. Both\n   * halves are idempotent — accepting an already-accepted task succeeds, and a\n   * repeat claim answers `already_claimed` — so a pass that dies halfway is\n   * safe to replay on the next tick.\n   */\n  private async runTasks(account: WorkBuddyAccount): Promise<{\n    claimed: number\n    credit: number\n    energy: number\n    claimableCount: number\n    /** Reward titles collected on this pass, for the card to list. */\n    titles: readonly string[]\n  }> {\n    const credential = account.credential\n    const tasks = await this.client.listTasks(credential)\n\n    const open = tasks\n      .filter(task => task.acceptStatus === 'not_accepted' && !task.locked)\n      .map(task => task.taskCode)\n    if (open.length > 0) await this.client.acceptTasks(credential, open)\n\n    // Re-read once more: pass 1 may have lit up tasks in the meantime, and their\n    // scoring has had time to land by the time this pass starts.\n    const refreshed = await this.client.listTasks(credential)\n    const claimable = refreshed.filter(task => task.claimable && !task.locked)\n\n    let credit = 0\n    let energy = 0\n    let claimed = 0\n    const titles: string[] = []\n    for (const task of claimable) {\n      if (this.stopped) break\n      const reward = await this.client.claimTaskReward(credential, task.taskCode)\n      credit += reward.credit\n      energy += reward.energy\n      if (reward.credit > 0 || reward.energy > 0) {\n        claimed++\n        titles.push(task.title)\n        this.logger.info?.(`automation claim ${account.label}: ${task.title} +${reward.credit}c +${reward.energy}e`)\n      } else {\n        // already_claimed: the reward was collected on an earlier pass.\n        this.logger.info?.(`automation claim ${account.label}: ${task.taskCode} already claimed`)\n      }\n      if (this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n    }\n\n    return { claimed, credit, energy, claimableCount: claimable.length, titles }\n  }\n\n  /**\n   * Streak redemption plus the lottery it unlocks.\n   *\n   * Tiers unlock on consecutive active days (7/14/28). Redeeming one pays\n   * credits, energy, a makeup card and — the part nothing else grants — lottery\n   * draws, so the draw runs straight after and only for the chances in hand.\n   *\n   * Everything here is idempotent: a tier already claimed is skipped by its\n   * status, and a draw consumes one chance, so a replay cannot double-spend.\n   */\n  private async redeemStreak(account: WorkBuddyAccount): Promise<string | undefined> {\n    const credential = account.credential\n    const status = await this.client.growthStreakFull(credential)\n\n    for (const tier of status.tiers) {\n      if (this.stopped) return\n      // `locked` is not a failure — it is the normal state until enough days\n      // accumulate — and `claimed` needs no action.\n      if (tier.status === 'locked' || tier.status === 'claimed') continue\n      try {\n        await this.client.redeemStreakTier(credential, tier.tier)\n        this.logger.info?.(`automation streak ${account.label}: redeemed ${tier.tier} (+${tier.credit}c +${tier.energy}e +${tier.chances} draw(s))`)\n        this.recordEarnings(account.id, dayKey(this.now()), { bonusCredit: tier.credit })\n      } catch (error: unknown) {\n        this.logger.warn?.(`automation streak ${account.label}: redeem ${tier.tier} failed:`, error)\n      }\n      if (this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n    }\n\n    // Draw whatever the redemptions just granted, plus anything left over.\n    const chances = await this.client.lotteryChances(credential)\n    for (let draw = 0; draw < chances; draw += 1) {\n      if (this.stopped) return\n      try {\n        const prize = await this.client.lotteryDraw(credential)\n        this.logger.info?.(`automation lottery ${account.label}: draw ${draw + 1}/${chances} -> ${JSON.stringify(prize).slice(0, 120)}`)\n      } catch (error: unknown) {\n        this.logger.warn?.(`automation lottery ${account.label}: draw failed:`, error)\n        // Stop drawing on the first failure: the loop is bounded by the count\n        // read before it started, and a failing draw would otherwise spin.\n        break\n      }\n      if (this.delayMs > 0 && !this.stopped) await sleep(this.delayMs)\n    }\n\n    // Nothing to redeem yet is the normal state, not a fault: hand back the\n    // countdown so the card can say \"5 more days\" instead of showing a row that\n    // looks like it silently failed.\n    const pendingTier = status.tiers.find(tier => tier.status === 'locked')\n    if (pendingTier !== undefined) {\n      const remaining = Math.max(0, pendingTier.days - status.days)\n      return remaining > 0\n        ? `${pendingTier.tier} in ${remaining}d`\n        : `${pendingTier.tier} ready`\n    }\n    return undefined\n  }\n\n  /**\n   * One trip through the buddy travel loop for an account.\n   *\n   * A single pass advances the state machine by at most one step: a trip\n   * that has arrived is collected, and an idle buddy is sent out. A buddy\n   * already travelling is left alone — there is nothing to do until it lands.\n   *\n   * Measured against the live upstream: the departed trip reports\n   * `dailyLimitReached` immediately, so the once-a-day limit needs no local\n   * bookkeeping.\n   */\n  private async runTravel(account: WorkBuddyAccount): Promise<void> {\n    const credential = account.credential\n    const buddy = await this.client.buddyInfo(credential)\n    if (buddy === undefined) {\n      // No buddy yet: adoption is gated on that day's activity report, which\n      // the report job has already sent by the time this runs. A rejection\n      // here means the gate is not met yet, which is normal, not an error.\n      try {\n        await this.client.buddyAgree(credential)\n        await this.client.buddyAdoptFirst(credential)\n        this.logger.info?.(`automation travel ${account.label}: adopted first buddy`)\n      } catch (error: unknown) {\n        this.logger.info?.(`automation travel ${account.label}: adoption not available yet` + ' (' + String(error).slice(0, 80) + ')')\n      }\n      return\n    }\n\n    const travel = await this.client.buddyTravelStatus(credential)\n    if (travel.state === 'arrived') {\n      if (travel.recordId === 0) {\n        // Arrived without a trip id cannot be claimed; nothing to do.\n        this.logger.warn?.(`automation travel ${account.label}: arrived but no record id`)\n        return\n      }\n      const reward = await this.client.buddyTravelClaim(credential, travel.recordId)\n      this.recordEarnings(account.id, dayKey(this.now()), { travelCredit: reward })\n      this.logger.info?.(`automation travel ${account.label}: claimed trip +${reward}c`)\n      return\n    }\n\n    if (travel.state === 'idle' && !travel.dailyLimitReached) {\n      await this.client.buddyTravelDepart(credential)\n      this.logger.info?.(`automation travel ${account.label}: departed (arrives later, claimed next pass)`)\n      return\n    }\n\n    this.logger.info?.(`automation travel ${account.label}: nothing to do (state=${travel.state})`)\n  }\n\n  /**\n   * Collect the running service-outage compensation offer, if any.\n   *\n   * Read-then-claim, rather than claim-blind: a claim costs one mutation the\n   * upstream may reject, and the status call is a free read that also tells us\n   * the size on offer so the ledger records the real number instead of\n   * assuming the usual 500.\n   *\n   * Returns the credits collected — 0 when there was nothing to collect, which\n   * is the normal case for most of the year.\n   */\n  private async runCompensation(account: WorkBuddyAccount): Promise<{ credit: number }> {\n    const credential = account.credential\n    const status = await this.client.fetchCompensationStatus(credential)\n    if (!status.active || status.claimed || status.creditNum <= 0) {\n      return { credit: 0 }\n    }\n    const claim = await this.client.claimCompensation(credential)\n    if (!claim.claimed) return { credit: 0 }\n    // Upstream repeats the amount on the claim response; fall back to the\n    // status read when it does not, since the status number is authoritative.\n    const credit = claim.creditNum > 0 ? claim.creditNum : status.creditNum\n    this.recordEarnings(account.id, dayKey(this.now()), { compensationCredit: credit })\n    return { credit }\n  }\n}\n"
    },
    {
      "path": "src/shim.ts",
      "content": "/**\n * Loopback OpenAI-compatible endpoint with multi-account failover.\n *\n * The pi-ai provider points here. Each chat request acquires an account from\n * the pool; when the upstream answers with a rate limit, the shim cools that\n * account down, takes the next one, and retries in the same request — so a\n * `429 soft_rate` never reaches the user as a turn failure.\n *\n * Security model (Host/Origin loopback checks, constant-time bearer compare,\n * random port, in-process secret, body cap, error→status mapping) follows\n * corrinehu/dsh-workbuddy-connect (MIT, Copyright (c) 2026 Corrine Hu), which\n * designed and validated it.\n *\n * @module dsh-xdpool/shim\n */\nimport { createHash, randomBytes, timingSafeEqual } from 'node:crypto'\nimport { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http'\nimport { Readable, Transform } from 'node:stream'\nimport type { WorkBuddyAccount, WorkBuddyAccountPool } from './accounts.ts'\nimport type { WorkBuddyCatalog } from './catalog.ts'\nimport { parseRateLimitReset, WorkBuddyUpstreamClient, type ChatStreamResult, type UpstreamErrorKind, type WorkBuddyRegion } from './upstream.ts'\nimport { compactWithSummary, estimateMessagesTokens, hardTruncate, type ChatMessage } from './context-budget.ts'\nimport { AggregateError, forwardAggregateStreamed, resolveAggregateProvider, type AggregateCatalog } from './aggregate.ts'\nimport { parseProviderModelId } from './providers.ts'\nimport {\n  COMBO_CHANNEL,\n  comboChain,\n  isComboId,\n  isComboRow,\n  resolveComboMember,\n  type ComboMember,\n  type ComboModelRow,\n} from './combos.ts'\nimport type { AggregateStore } from './store.ts'\nimport { paidAlternativeFor } from './siblings.ts'\nimport { inspectSseFrame, StreamTracker, type UsageRecorder } from './stats.ts'\nimport { FREE_CHANNEL, FREE_MODEL_PREFIX } from './free-catalog.ts'\nimport { ChannelRequestError, type ChannelLane } from './channel-lane.ts'\nexport interface ShimLogger {\n  info?(...args: unknown[]): void\n  warn(...args: unknown[]): void\n  error(...args: unknown[]): void\n}\nexport interface WorkBuddyShim {\n  ready: Promise<void>\n  baseUrl(): string\n  token(): string\n  /**\n   * Everything the gateway could serve, with display names.\n   *\n   * The card's model picker reads this; `/v1/models` maps the same entries down\n   * to ids. One source so the card cannot offer a model the gateway then refuses.\n   */\n  roster(): Promise<readonly GatewayModelEntry[]>\n  close(): Promise<void>\n}\n/**\n * One gateway-visible model: the id a client sends, the name a human reads, and\n * the lane it belongs to.\n *\n * Both are needed because they disagree in exactly the places that matter. A\n * qoder model is `qfmodel` on the wire and `Qwen3.8-Flash · 免费` in every\n * interface the user has met it in, and the OpenAI `/v1/models` schema has no\n * field for the second — so the name can only ever be shown here, on the card.\n */\nexport interface GatewayModelEntry {\n  id: string\n  name: string\n  source: string\n}\n/**\n * The namespace the gateway lists POOL rows under.\n *\n * The listing already speaks three prefixes — `combo:<slug>` for a chain,\n * `free:<model>` for the keyless lane, and a composite `providerId/modelId` for\n * every aggregate row — and only the pool's own models were listed bare. A\n * client reading `/v1/models` therefore could tell three lanes apart and could\n * not tell the fourth from anything else, which is the opposite of what a\n * listing is for.\n *\n * A prefix rather than a slash, because the slash IS the aggregate\n * discriminator: `parseProviderModelId` splits on the first `/`, so a prefixed\n * id spelled with a slash would be read as an aggregate row and sent to the\n * wrong lane.\n *\n * `buddy:` because that is what this lane is. `REGISTERED_CHANNELS` in\n * `channels.ts` gives `buddy` to WorkBuddy 国内版 (`copilot.tencent.com`) and\n * `workbuddy` to 国际版, and the relay is wired to `shims.cn` — the domestic\n * pool. Naming the lane after the vendor rather than after the mechanism keeps it\n * consistent with every channel row the gateway lists, and it leaves `workbuddy:`\n * free for the international pool whenever `shims.global` is exposed too.\n *\n * Bare pool ids keep being accepted. Clients configured before this existed are\n * not broken by it; they are just no longer the only way to say it.\n */\nexport const POOL_MODEL_PREFIX = 'buddy:'\n/**\n * The lane this shim's pool rows belong to, spelled the way the channel registry\n * spells it. Exported so the card and the channel listing can agree on which\n * channel ids the pool already covers instead of each keeping its own list.\n */\nexport const POOL_LANE_CHANNEL_ID = 'buddy'\n/**\n * Prefixes reserved for lane routing. A channel must not be listed under one of\n * these, because its rows would then be indistinguishable from the lane that\n * owns the prefix.\n */\nexport const RESERVED_MODEL_PREFIXES: readonly string[] = [\n  POOL_MODEL_PREFIX,\n  FREE_MODEL_PREFIX,\n  `${COMBO_CHANNEL}:`,\n]\n/**\n * Whether one channel id is already spoken for by a lane.\n *\n * The pool-owned ids are the interesting case rather than an accident: `buddy`\n * and `workbuddy` ARE account pools this plugin serves itself, so listing them\n * again as channels would offer the same models twice under two routes.\n */\nexport function channelListableAsRows(\n  channelId: string,\n  poolOwned: ReadonlySet<string> = new Set([POOL_LANE_CHANNEL_ID]),\n): boolean {\n  if (poolOwned.has(channelId)) return false\n  return !RESERVED_MODEL_PREFIXES.includes(`${channelId}:`)\n}\n/**\n * Everything the aggregate lane needs to answer one request.\n *\n * Optional on {@link WorkBuddyShimOptions} because most shims are pool-only: the\n * CLI and the tests never build an aggregate catalog, and making them supply one\n * would mean threading an argument nobody reads.\n */\nexport interface AggregateLaneOptions {\n  /** The rows currently offered, keyed by composite `providerId/modelId`. */\n  catalog: AggregateCatalog\n  /** Where the stored settings come from, re-read per request. */\n  readStore: () => AggregateStore\n}\nexport interface ExtraLaneOptions {\n  /**\n   * The免密 free lane: which rows exist right now, and where to send a turn.\n   *\n   * The row reader is consulted per request, exactly like the pool's catalog —\n   * a roster that refreshed after startup must be servable without a restart.\n   */\n  free: ExtraLaneSource\n}\nexport interface ExtraLaneSource {\n  /**\n   * The rows this lane offers.\n   *\n   * `name` is the human-facing display name the free catalog already keeps (a\n   * raw upstream id is deliberately never shown to a picker); it is optional\n   * here because the lane's own contract only ever needed the ids, and the\n   * gateway's model picker is the first consumer that wants the label too.\n   */\n  current: () => readonly { modelId: string; id: string; name?: string }[]\n  /**\n   * Run one turn, handing back the frames to write.\n   *\n   * The source owns the whole upstream conversation — the session identity, the\n   * wire conversion, the tool bookkeeping — and returns chat-wire SSE payloads,\n   * because that is the only wire this shim's caller speaks.\n   */\n  run: (options: {\n    modelId: string\n    body: string\n    signal: AbortSignal\n    onFrame: (payload: string) => void\n  }) => Promise<unknown>\n}\nexport interface WorkBuddyShimOptions {\n  pool: WorkBuddyAccountPool\n  client: WorkBuddyUpstreamClient\n  catalog: WorkBuddyCatalog\n  logger?: ShimLogger\n  /**\n   * Restrict this shim to one gateway. Two shims run side by side — one\n   * per region — and each must only ever draw accounts that belong to its\n   * own gateway. Absent means \"every account\" (a single-region deployment).\n   */\n  region?: WorkBuddyRegion\n  /** Max accounts to try per request before giving up. */\n  maxAttempts?: number\n  /**\n   * Where per-call usage goes.\n   *\n   * Optional so the CLI and the tests can run a shim with no dashboard: they\n   * assemble a pool without a panel, and forcing a recorder on them would mean\n   * threading an argument nobody reads.\n   */\n  usageRecorder?: UsageRecorder\n  /**\n   * The second lane: providers the user holds a key for.\n   *\n   * Attached to the CN shim only. The aggregate lane is gateway-independent — it\n   * has no region to filter by — so running it on both shims would expose the\n   * same models twice under two provider ids, and a user who picked one would\n   * have no way to tell which they were using.\n   */\n  aggregate?: AggregateLaneOptions\n  /**\n   * The third and fourth lanes: the pooled免密 gateway and the sealed co-paid\n   * relay.\n   *\n   * Also CN-shim-only, for the aggregate lane's reason plus one of their own: a\n   * second copy under the global provider id would list every model twice and\n   * give the user two names for one lane.\n   */\n  extra?: ExtraLaneOptions\n  /**\n   * The fifth lane: the 扫码登录 channels, reached through the host's own LLM\n   * seam rather than a socket this plugin owns.\n   *\n   * CN-shim-only for the aggregate lane's reason — a second copy under the\n   * global provider id would list every channel twice — and the relay is wired to\n   * this shim, so this is also the only shim the LAN gateway can see.\n   */\n  channels?: ChannelLane\n  /**\n   * The gateway allowlist, re-read per request.\n   *\n   * `undefined` means \"no selection has been made: serve everything to LAN\n   * clients too\", so upgrading cannot silently break a device already pointed at\n   * the relay. An empty array is the opposite answer — the user unticked\n   * everything — and is enforced as such.\n   *\n   * Only consulted for requests carrying {@link RELAY_HOP_HEADER}, which is the\n   * relay's own marker. The host's adapter reaches this same process without it,\n   * so the models DSH offers in its picker are never narrowed by a list meant\n   * for other machines.\n   */\n  lanModels?: () => readonly string[] | undefined\n}\nconst REQUEST_BODY_LIMIT = 64 * 1024 * 1024\n/**\n * Marked by the LAN relay on every request it forwards.\n *\n * Defined here rather than in `relay.ts` because the shim has to READ it, and\n * `relay.ts` already depends on this module — importing back would be a cycle.\n *\n * It is also the only safe way to scope the gateway allowlist. This one process\n * serves two very different callers: the host's own adapter (so every model\n * DSH's picker offers, and every turn the user has in chat) and, through the\n * relay, whatever device on the LAN holds the key. Gating the shim outright\n * would gate the user's own chat with it; gating on this header restricts the\n * LAN surface and leaves the host untouched.\n */\nexport const RELAY_HOP_HEADER = 'x-xdpool-relay-hop'\nconst LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost', '[::1]'])\n/** HTTP status each upstream failure class surfaces as. */\nconst KIND_STATUS: Readonly<Record<UpstreamErrorKind, number>> = {\n  hard_credit: 402,\n  soft_rate: 429,\n  session_dead: 401,\n  not_found: 502,\n  server: 502,\n  client: 400,\n}\nfunction hostnameOfHost(host: string): string {\n  let hostname = host.trim().toLowerCase()\n  if (hostname.startsWith('[')) {\n    const end = hostname.indexOf(']')\n    return end === -1 ? hostname : hostname.slice(0, end + 1)\n  }\n  const colon = hostname.lastIndexOf(':')\n  if (colon !== -1 && /^\\d+$/.test(hostname.slice(colon + 1))) hostname = hostname.slice(0, colon)\n  return hostname\n}\n/** Host must name loopback; drops DNS-rebinding attempts before routing. */\nfunction hostIsLoopback(host: string | undefined): boolean {\n  if (host === undefined || host.trim() === '') return false\n  return LOOPBACK_HOSTS.has(hostnameOfHost(host))\n}\n/** A present Origin must be loopback; non-browser clients send none and pass. */\nfunction originIsLoopback(origin: string | undefined): boolean {\